'use strict';
const $=id=>document.getElementById(id);
const classes=['cardboard','glass','metal','paper','plastic','trash'];
const KEY='sortloop.intake.v1.';
let session=null, busy=false, prediction=null, imageVersion=0, objectURL=null, page=0;
let currentImage='samples/cardboard.jpg';
let toastTimer;
function status(message){$('toast').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').textContent='',6000)}
function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function route(){let name=location.hash.slice(1)||'workspace';if(!['workspace','intakes','model'].includes(name))name='workspace';document.querySelectorAll('.page').forEach(el=>el.hidden=el.id!==name);document.querySelectorAll('nav a').forEach(el=>{const active=el.hash==='#'+name;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});if(name==='intakes')renderRecords()}
window.addEventListener('hashchange',route);
function setBusy(value){busy=value;$('analyze').disabled=value;$('analyze').classList.toggle('busy',value);$('analyze').innerHTML=value?'Analysing material… <span>◌</span>':'Identify material <span>↗</span>';document.querySelectorAll('.sample').forEach(b=>b.disabled=value);$('file').disabled=value;document.querySelector('.upload-row button').disabled=value}
function resetPrediction(){prediction=null;$('review-form').hidden=true;$('confirmed').checked=false;$('weight').value='';$('form-error').textContent='';$('result').innerHTML='<div class="ready-icon">⌁</div><h3>Ready for a closer look.</h3><p>Your image is ready. Identify the material, then review the suggestion.</p><div class="instruction">One item at a time. For best results, use a plain background.</div>';$('analysis-status').textContent='Ready to analyse. Photos stay on this device.';$('analysis-status').classList.remove('error')}
function chooseSample(c){if(busy)return;if(objectURL){URL.revokeObjectURL(objectURL);objectURL=null}imageVersion++;currentImage='samples/'+c+'.jpg';$('preview').src=currentImage;$('preview').alt='Held-out TrashNet example: '+c;$('image-label').textContent='Test-set example · '+c;document.querySelectorAll('.sample').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.material===c)));resetPrediction()}
async function chooseFile(file){if(busy||!file)return;const version=++imageVersion;const error=(!['image/jpeg','image/png','image/webp'].includes(file.type))?'Choose a JPG, PNG or WebP image.':file.size>10*1024*1024?'That file is too large. Choose an image under 10 MB.':!file.size?'That image is empty. Choose another photo.':null;if(error){$('analysis-status').textContent=error;$('analysis-status').classList.add('error');return}const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(version!==imageVersion){URL.revokeObjectURL(url);return}if(img.naturalWidth*img.naturalHeight>40000000)throw Error('Image exceeds 40 megapixels. Resize it before trying again.');if(objectURL)URL.revokeObjectURL(objectURL);objectURL=url;currentImage=url;$('preview').src=url;$('preview').alt='Selected material photograph';$('image-label').textContent=file.name;document.querySelectorAll('.sample').forEach(b=>b.setAttribute('aria-pressed','false'));resetPrediction()}catch(e){URL.revokeObjectURL(url);$('analysis-status').textContent=e.message.includes('megapixels')?e.message:'This image could not be opened. Try another JPG or PNG.';$('analysis-status').classList.add('error')}}
$('file').addEventListener('change',e=>{chooseFile(e.target.files[0]);e.target.value=''});
$('dropzone').addEventListener('dragover',e=>{e.preventDefault();if(!busy)$('dropzone').classList.add('dragging')});$('dropzone').addEventListener('dragleave',()=>$('dropzone').classList.remove('dragging'));$('dropzone').addEventListener('drop',e=>{e.preventDefault();$('dropzone').classList.remove('dragging');chooseFile(e.dataTransfer.files[0])});
function preprocess(img){const canvas=document.createElement('canvas');canvas.width=160;canvas.height=160;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.fillStyle='#fff';ctx.fillRect(0,0,160,160);ctx.drawImage(img,0,0,160,160);const rgba=ctx.getImageData(0,0,160,160).data;const data=new Float32Array(3*160*160);const mean=[.485,.456,.406],std=[.229,.224,.225];for(let p=0;p<160*160;p++)for(let c=0;c<3;c++)data[c*160*160+p]=(rgba[4*p+c]/255-mean[c])/std[c];return data}
async function loadModel(){if(session)return session;if(!window.ort)throw Error('Inference runtime could not load. Reload this page and try again.');ort.env.wasm.wasmPaths=new URL('vendor/',location.href).href;ort.env.wasm.numThreads=1;ort.env.wasm.proxy=false;const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),60000);try{const response=await fetch('model/sortloop.onnx',{signal:controller.signal});if(!response.ok)throw Error('Model download failed. Check your connection and try again.');const bytes=await response.arrayBuffer();session=await ort.InferenceSession.create(bytes,{executionProviders:['wasm'],graphOptimizationLevel:'all'});return session}finally{clearTimeout(timeout)}}
async function analyze(){if(busy)return;setBusy(true);$('analysis-status').classList.remove('error');$('analysis-status').textContent=session?'Reading the material…':'Loading the CNN. The first analysis may take a moment…';prediction=null;$('review-form').hidden=true;try{const model=await loadModel();const img=new Image();img.src=currentImage;await img.decode();const tensor=new ort.Tensor('float32',preprocess(img),[1,3,160,160]);const output=await model.run({image:tensor});const logits=Array.from(output.logits.data);const max=Math.max(...logits),exps=logits.map(x=>Math.exp(x-max)),sum=exps.reduce((a,b)=>a+b,0);const scores=classes.map((name,i)=>({name,score:exps[i]/sum})).sort((a,b)=>b.score-a.score);prediction=scores[0];$('result').innerHTML='<p class="eyebrow">MODEL SUGGESTION · REVIEW REQUIRED</p><div class="prediction-title"><strong>'+prediction.name+'</strong><span>'+Math.round(prediction.score*100)+'%</span></div><p>Model score, not a guarantee. '+(prediction.score<.65?'The model is uncertain. Check this item carefully.':'Confirm the actual material before saving.')+'</p>'+scores.slice(0,3).map(x=>'<div class="bar-row"><span>'+x.name+'</span><div class="bar"><i style="width:'+x.score*100+'%"></i></div><span>'+Math.round(x.score*100)+'%</span></div>').join('');$('material').value=prediction.name;$('confirmed').checked=false;$('form-error').textContent='';$('review-form').hidden=false;$('analysis-status').textContent='Analysis complete. Review the suggestion below.'}catch(e){$('analysis-status').textContent=e.name==='AbortError'?'Download timed out. Check your connection, then try again.':'Analysis failed. '+(e.message||'Please try again.');$('analysis-status').classList.add('error')}finally{setBusy(false)}}
function readRecords(){const rows=[];try{for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(!key?.startsWith(KEY))continue;try{const r=JSON.parse(localStorage.getItem(key));if(r&&typeof r.id==='string'&&typeof r.date==='string'&&[...classes,'unknown'].includes(r.material)&&classes.includes(r.suggested)&&Number.isFinite(r.score)&&(r.weight===null||(Number.isFinite(r.weight)&&r.weight>0)))rows.push(r)}catch{}}}catch{status('Browser storage is unavailable. Enable storage to keep an intake log.')}return rows.sort((a,b)=>b.date.localeCompare(a.date))}
$('review-form').addEventListener('submit',e=>{e.preventDefault();if(!prediction)return;const weight=$('weight').value.trim();const n=weight===''?null:Number(weight);$('weight').removeAttribute('aria-invalid');$('confirmed').removeAttribute('aria-invalid');if(weight!==''&&(!Number.isFinite(n)||n<=0||n>10000)){$('form-error').textContent='Enter a weight above 0 and no more than 10,000 kg, or leave it blank.';$('weight').setAttribute('aria-invalid','true');$('weight').focus();return}if(!$('confirmed').checked){$('form-error').textContent='Confirm that you reviewed the material before saving.';$('confirmed').setAttribute('aria-invalid','true');$('confirmed').setAttribute('aria-describedby','form-error');$('confirmed').focus();return}const row={id:crypto.randomUUID(),date:new Date().toISOString(),material:$('material').value,suggested:prediction.name,score:prediction.score,weight:n};try{localStorage.setItem(KEY+row.id,JSON.stringify(row));prediction=null;$('review-form').hidden=true;page=0;location.hash='intakes';renderRecords();status('Reviewed intake saved to this browser.')}catch{$('form-error').textContent='Could not save. Browser storage may be full or disabled. Your entries are still here.'}});
function renderRecords(){const all=readRecords();$('nav-count').textContent=all.length;$('total-count').textContent=all.length;$('total-weight').textContent=all.reduce((s,r)=>s+(r.weight||0),0).toLocaleString('en-GB',{maximumFractionDigits:3});const filter=$('filter').value;const rows=all.filter(r=>filter==='all'||r.material===filter);page=Math.max(0,Math.min(page,Math.ceil(rows.length/10)-1));const visible=rows.slice(page*10,page*10+10);$('records').innerHTML=visible.length?visible.map(r=>'<tr><td>SL-'+escapeHTML(r.id.slice(0,6).toUpperCase())+'</td><td>'+escapeHTML(r.material==='unknown'?'Unknown / manual review':r.material)+'</td><td>'+escapeHTML(r.suggested)+' · '+Math.round(r.score*100)+'%</td><td>'+(r.weight===null?'Not recorded':r.weight.toLocaleString('en-GB',{maximumFractionDigits:3})+' kg')+'</td><td>'+escapeHTML(new Date(r.date).toLocaleString('en-GB',{timeZone:'Asia/Jakarta',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}))+'</td></tr>').join(''):'<tr><td class="empty" colspan="5">'+(all.length?'No intakes match this material. Try another filter.':'Your first reviewed intake belongs here. Start in the workspace.')+'</td></tr>';$('range').textContent=rows.length?`${page*10+1}–${Math.min(page*10+10,rows.length)} of ${rows.length} intakes`:'0 intakes';$('prev').disabled=page===0;$('next').disabled=(page+1)*10>=rows.length}
function changePage(delta){page+=delta;renderRecords()}
function exportCSV(){const rows=readRecords();if(!rows.length){status('No saved intakes yet. Review and save a material first.');return}const csv=['id,saved_at_utc,reviewed_material,model_suggestion,model_score,weight_kg',...rows.map(r=>[r.id,r.date,r.material,r.suggested,r.score.toFixed(6),r.weight??''].join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='sortloop-intakes-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('Exported '+rows.length+' intakes.')}
$('filter').addEventListener('change',()=>{page=0;renderRecords()});window.addEventListener('storage',e=>{if(e.key?.startsWith(KEY)||e.key===null)renderRecords()});
for(const c of classes){const button=document.createElement('button');button.type='button';button.className='sample';button.dataset.material=c;button.setAttribute('aria-pressed',String(c==='cardboard'));button.setAttribute('aria-label','Use '+c+' test-set example');button.innerHTML='<img src="samples/'+c+'.jpg" alt=""><span>'+c+'</span>';button.addEventListener('click',()=>chooseSample(c));$('samples').append(button)}
for(const c of [...classes,'unknown']){const label=c==='unknown'?'Unknown / manual review':c[0].toUpperCase()+c.slice(1);for(const id of ['material','filter']){const option=document.createElement('option');option.value=c;option.textContent=label;$(id).append(option)}}
fetch('metrics.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(m=>{$('metrics').innerHTML='<div><span>'+ (m.accuracy*100).toFixed(1)+'%</span><p>Held-out test accuracy · '+m.split.test+' images</p></div><div><span>'+(m.report['macro avg']['f1-score']*100).toFixed(1)+'%</span><p>Macro F1 · all six classes</p></div><div><span>'+m.dataset_count.toLocaleString('en-GB')+'</span><p>Images after exact duplicate removal</p></div>';$('class-results').innerHTML=m.classes.map(c=>'<div class="bar-row"><span>'+c+'</span><div class="bar"><i style="width:'+100*m.report[c]['f1-score']+'%"></i></div><span>'+Math.round(100*m.report[c]['f1-score'])+'%</span></div>').join('')}).catch(()=>{$('metrics').textContent='Evaluation data could not load. Reload to retry, or download the report.'});
renderRecords();route();
